-- Actualizar why_json con alojamientos y actividades
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales rústicas, apartamentos de montaña independientes rodeados de castañares viejos, cortijos tradicionales rehabilitados y complejos de ecoturismo rural junto al río Genil con chimenea de leña. | Vertiente norte de Sierra Nevada alta, cabecera del río Genil. Destaca por la famosa ruta senderista del Tranvía de la Sierra (itinerario plano que aprovecha el antiguo trazado ferroviario minero cruzando túneles en la roca y puentes sobre el río), acceso norte al sendero alpino Vereda de la Estrella bajo las caras norte de los "tres miles" (Mulhacén y Alcazaba), dehesas forestales de castaños milenarios y recolección micológica.') WHERE codigo_ine = '18094';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales granadinas con huertos frutales a orillas del río, hoteles rurales de ribera con encanto, apartamentos rústicos y alojamientos de interior especializados en cicloturismo de carretera. | Puerta natural de acceso a los valles altos de Sierra Nevada, bañado por el río Genil. Ofrece la ruta de senderismo fluvial del Canal de la Espartera, paseos botánicos y dehesas agrícolas de su vega tradicional bajo túneles vegetales de álamos y sauces, rutas cicloturistas exigentes que ascienden hacia el Purche o Sierra Nevada, y zonas recreativas de agua dulce. PROVINCIA: GRANADA (Andalucía - Municipios Nuevos)') WHERE codigo_ine = '18157';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales de piedra de cantería con patios andaluces rústicos, palacetes de interior con encanto y apartamentos rurales de campiña alta. | Estribaciones de Sierra Morena, a las orillas del Embalse de Rumblar. Ofrece rutas de senderismo arqueológico hacia el yacimiento de la Edad del Bronce de Peñalosa, paseos llanos que rodean su imponente castillo omeya del siglo X (el más antiguo de Europa), kayak de interior, y dehesas con certificación Starlight.') WHERE codigo_ine = '24012';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales serranas vinculadas al agroturismo de castaños y vides, posadas con chimeneas rústicas y apartamentos turísticos de alta montaña. | En pleno Parque Nacional Sierra de las Nieves. Destaca por albergar el mirador de Luis Ceballos. Rutas de senderismo bajo inmensos bosques de pinsapos y densos castañares que tiñen el paisaje en otoño, y caminatas que conectan con la meseta caliza alta de Quejigales.') WHERE codigo_ine = '29100';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales con fachadas de mampostería antigua y calles empedradas rústicas, apartamentos boutique rurales con encanto en el casco medieval. | Faldas del cerro de San Cristóbal. Alberga una mezquita rural del siglo X conservada casi intacta erigida sobre las ruinas de un castillo. Ofrece la ruta de senderismo de ascensión al Pico de San Cristóbal, paseos botánicos por el arroyo de la Acebuche, caminatas de dehesa agraria y avistamiento de aves rapaces.') WHERE codigo_ine = '22001';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares con portadas tradicionales adornadas con "llanos" (alfombras artesanales de piedras bicolores en el suelo de entrada), y apartamentos rústicos pequeños. | Enclavado en un valle cerrado profundo de colinas ganaderas del Parque Natural Sierra de Aracena. Ofrece paseos de aislamiento absoluto y silencio rural, rutas de senderismo plano por el Sendero de las Suertes, caminatas micológicas otoñales extremas en dehesas de encinas y robles. 📂 PROVINCIA: CÁCERES (Extremadura Municipios Nuevos)') WHERE codigo_ine = '21045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural con una de las arquitecturas de piedra mejor conservadas del Pirineo occidental y alojamientos con suelos de losa tradicional. | Parque Natural de los Valles Occidentales. Destaca por la ruta senderista del Valle de Zuriza, caminatas de alta montaña en el entorno kárstico de Linza, senderos botánicos entre abetales salvajes y territorio histórico de los últimos osos autóctonos.') WHERE codigo_ine = '22028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra maciza y pizarra, parador de turismo de montaña en el valle, y albergues para excursionistas. | Acceso directo al Valle de Pineta dentro del Parque Nacional de Ordesa. Ofrece las rutas de senderismo de ascensión al Balcón de Pineta y al Lago de Marboré, caminatas bajo cascadas espectaculares, senderos forestales alpinos y conexión a Francia mediante túnel. 📂 PROVINCIA: LLEIDA (Cataluña - Municipios Nuevos)') WHERE codigo_ine = '22057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Palacetes rurales rústicos con fachadas de cal y vigas de madera vista, apartamentos rústicos acogedores y alojamientos de ribera junto al Arlanza. | Valle del río Arlanza. Ofrece la ruta senderista del Sendero del Buen Conde, caminatas hacia las ruinas del Monasterio de San Pedro de Arlanza (rodeado de inmensos bosques de encinas y sabinas de roca), senderos cicloturistas de llanura alta y paseos de interpretación del valle fluvial. 📂 PROVINCIA: SORIA (Castilla y León Municipios Nuevos)') WHERE codigo_ine = '09113';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales castellanas integradas en palacios renacentistas y conventos restaurados, casas de turismo rural a la sombra de su colosal castillo fortificado y apartamentos rurales familiares. | Tierra de Frontera de la meseta del Duero. Destaca por albergar en su término la espectacular Ermita de San Baudelio de Berlanga (joya mozárabe aislada en pleno paisaje agrario árido y dehesa caliza). Ofrece rutas de senderismo fluvial por el río Escalote, caminatas hacia las dehesas de encinas centenarias del cañón del Duero meridional, observación astronómica nocturna y ornitología.') WHERE codigo_ine = '42035';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña colgadas literalmente en terrazas sobre el risco, pequeños hostales de montaña con chimeneas de campana y viviendas rurales con espectaculares miradores al barranco. | Encaramado de forma inverosímil a una colosal muela de roca caliza a 1.195 metros de altitud. Ofrece rutas de senderismo geológico por los barrancos de la Mola d''Ares, caminatas hacia el Barranc dels Horts (un paraje natural sagrado con un bosque de robles y quejigos centenarios monumentales único en el levante peninsular), observación de grandes colonias de buitre leonado y cabra montés, y senderos micológicos.') WHERE codigo_ine = '11002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra medieval rehabilitada en un casco histórico galardonado, masías de agroturismo ganadero independientes en el altiplano y apartamentos rústicos con porche. | Comarca del Alt Maestrat montañoso. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo exigentes hacia el barranco del río Monleón, caminatas para ver el colosal "Carrasca de Culla" (una encina monumental milenaria protegida bajo cuya copa se cobijaban ejércitos), observación astronómica en su observatorio turístico del Astromestrat con cielos negros certificados, y micología. PROVINCIA: TERUEL (Aragón - Municipios Nuevos)') WHERE codigo_ine = '12051';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales con espectaculares aleros de madera tallada a mano, hoteles boutique rurales con patios interiores ajardinados y posadas medievales de piedra (Premio Europa Nostra por su conservación). | Piedemonte de la Sierra de Gúdar. Ofrece la ruta senderista del río Mijares, senderos de interpretación botánica por dehesas de sabinas y encinas viejas, rutas ecuestres de montaña y es una de las zonas de máxima nitidez nacional para la observación de estrellas al contar con certificación Starlight de cielos negros limpios.') WHERE codigo_ine = '44201';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo rural intramuros integradas en un conjunto arquitectónico medieval gótico intacto y protegido, y palacetes de la Orden del Temple habilitados para pernocta rústica. | Corazón del Maestrazgo profundo. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo hacia el cercano Monumento Natural de las Cuevas de Cañart, caminos tradicionales de herradura delimitados por interminables muros de piedra seca y caminatas por riberas de montaña calizas secas. 📂 PROVINCIA: GUADALAJARA (Castilla-La Mancha - Municipios Nuevos)') WHERE codigo_ine = '44149';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos forestales integrados en pequeños núcleos del valle y albergues de naturaleza fluvial. | Centro geográfico y de interpretación del Parque Natural del Alto Tajo. Alberga el espectacular paraje de la Escaleruela y el Mirador de Zaorejas colgado sobre un meandro vertical cerrado con caídas de roca de más de 150 metros. Rutas de senderismo de cañón de río bajo túneles de pinos laricios, quejigos y tejos salvajes, caminatas micológicas y observación astronómica (cielos negros certificados Starlight).') WHERE codigo_ine = '19333';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de aldea de mampostería de piedra tradicionales de montaña alta de aislamiento, apartamentos rústicos pequeños con chimenea de piedra de suelo y albergues forestales de paso. | Límite noroccidental de la Sierra Norte alta, frontera con Segovia. Custodia el Parque Natural del Hayedo de Tejera Negra (Patrimonio de la Humanidad por la UNESCO). Espectaculares y protegidas rutas de senderismo botánico otoñal (Senda de las Carretas) bajo las hayas centenarias mezcladas con tejos, abedules y acebos mágicos, senderos pastoriles de montaña y recolección micológica. 📂 PROVINCIA: ÁVILA (Castilla y León Municipios Nuevos)') WHERE codigo_ine = '19065';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería de granito con corredores de madera, hoteles rurales de ribera junto al río Tormes, antiguas fábricas de luz reconvertidas en alojamientos rústicos y casas de labranza tradicionales. | Nudo estratégico occidental del Valle del Tormes y el Aravalle, a los pies de Gredos. Ofrece las rutas de senderismo fluvial del río Tormes cruzando su monumental puente románico, caminatas de media montaña que se adentran en el Valle del Jerte colindante, senderos micológicos de robledal, paseos a caballo y agroturismo enfocado en la cultura agrícola tradicional del judión del Barco.') WHERE codigo_ine = '51009';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alberga el primer Parador de Turismo histórico de España, hoteles forestales mimetizados entre el pinar, casas de aldea tradicionales de cantería y chalets rústicos de montaña. | Cabecera alta del Valle del Tormes, a más de 1.500 metros de altitud. Destaca por albergar el Nacimiento del Río Tormes en el paraje de las Chorreras. Ofrece la ruta de senderismo del Pinar de Navarredonda (un inmenso bosque de pino silvestre autóctono), caminatas ecuestres de montaña alta, senderos micológicos otoñales y es un punto de referencia para el turismo de observación de estrellas (Starlight). 📂 PROVINCIA: SEGOVIA (Castilla y León Municipios Nuevos)') WHERE codigo_ine = '05165';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas porticadas tradicionales con solanas de madera que miran a la plaza elíptica, chalets de montaña independientes con chimenea de leña, y hoteles rurales de campo adaptados para familias y deportistas de nieve. | Piedemonte de la Sierra de Ayllón y nexo con la estación de esquí de La Pinilla. Custodia el espectacular Hayedo de la Pedrosa (uno de los hayedos más meridionales de la península). Ofrece la ruta de las dehesas de robles melojos, caminatas botánicas otoñales, rutas de agroturismo hacia los célebres Pueblos Negros y Amarillos (como Madriguera o Alquite) integrados en su término, y micología de boletus.') WHERE codigo_ine = '40170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de interior colgadas literalmente sobre el risco medieval amurallado, posadas con encanto rústico con vistas panorámicas al agua y apartamentos rurales para amantes del silencio. | Custodia la entrada occidental al Parque Natural de las Hoces del Río Riaza y está bañado por el Embalse de Linares del Arroyo. Ofrece rutas de senderismo geológico y ornitológico bordeando el profundo desfiladero calizo (Refugio de Rapaces de Montejo), piragüismo, vela y deportes náuticos sin motor en el embalse, paseos botánicos por sabinares centenarios y observación astronómica de cielos negros. 📂 PROVINCIA: TARRAGONA (Cataluña Municipios Nuevos)') WHERE codigo_ine = '40115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas de piedra arenisca roja (pedra roja) tradicionales de montaña con cubiertas de losa, hostales rurales familiares con grandes chimeneas de piedra de leña y apartamentos forestales mimetizados bajo las pinadas. | Conocida como la "Vila Vermella", en el corazón del espacio protegido de las Montañas de Prades a casi 1.000 metros de altitud. Destaca por la ruta de senderismo hacia la Roca Foradada (un espectacular arco natural de roca arenisca en mitad del bosque), caminatas botánicas bajo frondosos castañares y robledales, senderos micológicos otoñales extremos (recogida de robellones), y es un destino con certificación astronómica internacional Starlight.') WHERE codigo_ine = '43116';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos cueva tradicionales rehabilitados en barrios históricos colgados, apartamentos rústicos de interior y casas de campo de labranza tradicionales de la vega del río. | Altiplano granadino nororiental, integrado en el Geoparque de Granada (UNESCO). Ofrece rutas de senderismo arqueológico de primer nivel hacia el yacimiento argárico de Castellón Alto (poblado de la Edad del Bronce excavado de forma virgen en la roca de la colina) y la necrópolis ibérica de Tútugi, senderos llanos de cicloturismo familiar entre badlands de yeso y observación astronómica nocturna.') WHERE codigo_ine = '18082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de piedra tradicionales calizas del prepirineo penibético, apartamentos rústicos pequeños en valles de pinos resineros. | Vertiente norte del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Rutas de senderismo forestal por el sendero del río Bacal, caminatas de media montaña que exploran densos pinares de repoblación viejos, dehesas y senderos micológicos de otoño (recogida de níscalos) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '18107';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo tradicionales del Valle de Lecrín rodeadas de campos de azahar, apartamentos rústicos con chimenea de leña y fincas de agroturismo. | Valle de Lecrín, zona de transición entre Sierra Nevada y la costa. Destaca por el Monumento Natural de la Falla de Nigüelas (colosal fenómeno geológico de fractura de roca visible a pie de pueblo). Rutas senderistas de la senda de los Molinos de agua, paseos botánicos por los jardines románticos de Müller y senderos agrícolas. 📂 PROVINCIA: JAÉN (Andalucía - Ampliación de Densidad)') WHERE codigo_ine = '18143';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas de sillería dorada con amplios jardines y huertos tradicionales, apartamentos de turismo de montaña rústicos. | Cara sur de Sierra Mágina. Rutas senderistas de interpretación botánica que exploran los lapiaces calcáreos altos, caminatas hacia los pinsapares de repoblación viejos en el barranco del Gualijar, dehesas ganaderas, recolección de setas en temporada en quejigales y senderos ganaderos tradicionales de montaña.') WHERE codigo_ine = '23044';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales de montaña con acabados en madera de pino, casas rurales familiares independientes junto a riachuelos trucheros limpios y cabañas de pinar. | Extremo norte de la Sierra de Segura, frontera con Albacete. Rutas de senderismo hacia el paraje de la Peña del Olivar, caminatas exigentes de ascensión a la Cambrón, dehesas, senderos micológicos otoñales extremos bajo densos bosques de pino negral y paseos fluviales por el río Guadalimar joven.') WHERE codigo_ine = '23082';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de pueblo tradicionales de interior, apartamentos rústicos acogedores para familias y grupos pequeños y alojamientos vinculados a huertos. | Piedemonte de la Sierra de Segura. Rutas de senderismo que siguen la Senda del río Beas bajo túneles vegetales umbríos de alisos, dehesas forestales linderas, caminatas micológicas, paseos fotográficos de olivares de campiña y cicloturismo de carretera sin tráfico.') WHERE codigo_ine = '24013';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas forestales de madera integradas bajo encinares, hostales rurales especializados en turismo de paso e histórico y apartamentos rústicos de pinar. | Custodia el Parque Natural de Despeñaperros. Sede de las colosales formaciones geológicas de "Los Órganos de Despeñaperros" (paredes verticales de cuarcita espectaculares cortadas por la fractura de la falla). Rutas de senderismo hacia el barranco de la Valdeazores, dehesas y senderos hacia las pinturas rupestres prehistóricas del Collado de los Jardines y avistamiento de ciervos. 📂 PROVINCIA: MÁLAGA (Andalucía - Ampliación de Densidad)') WHERE codigo_ine = '23076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Eco-lodges de diseño sostenible integrados en la dehesa mediterránea, casas rurales unifamiliares tranquilas y pequeños hoteles con encanto rústico. | Vertiente sur de la Sierra de las Nieves (Sierra Blanca). Ofrece la ruta de senderismo del Sendero de Juanar, caminatas botánicas bajo frondosos alcornocales y olivares de montaña, dehesas mediterráneas, paseos hacia el Refugio de Juanar, observación de fauna ibérica (cabra montés) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '29076';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Fincas ganaderas andaluzas con casas de labranza tradicionales encaladas, apartamentos rústicos a la sombra de su castillo enriscado y alojamientos con encanto. | Paraje Natural de Sierra Crestellina y transición al Campo de Gibraltar. Destaca por el sendero de los Arroyos, dehesas y caminatas de observación ornitológica de grandes aves rapaces (colonia protegida de buitre leonado anidando frente a la costa del Mediterráneo), senderos geológicos en riscos calizos y baños de agua dulce mineromedicinal en los Baños de la Hedionda (baños romanos).') WHERE codigo_ine = '29041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos tradicionales de la serranía de Ronda con acabados en madera de castaño, casas rurales pequeñas e independientes junto a la estación de tren rural y cabañas de madera forestales. | Valle del río Guadiaro, Parque Natural de Grazalema bajo. Destaca por el Sendero del Guadiaro (itinerario de senderismo fluvial paralelo a la vía del ferrocarril que conecta con Benaoján), piragüismo fluvial, kayak y descenso de ríos en aguas limpias de montaña, dehesas y senderos micológicos de encinar húmedo.') WHERE codigo_ine = '29063';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de pueblo tradicionales serranas de mampostería estrecha, apartamentos rústicos acogedores para familias y espeleólogos cerca de las estaciones fluviales. | Serranía de Ronda kárstica. Custodia la imponente Cueva del Gato (Monumento Natural célebre por su colosal boca de roca de la que brota un río de agua helada y cristalina en forma de cascada y poza natural apta para el baño veraniego) y la Cueva de la Pileta (pinturas rupestres prehistóricas). Rutas senderistas de montaña, dehesas mediterráneas y paseos fluviales por el Guadiaro. 📂 PROVINCIA: ASTURIAS (Principado de Asturias - Ampliación de Densidad)') WHERE codigo_ine = '29028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Teitos tradicionales rehabilitados (antiguas cabañas ganaderas de piedra con techumbre de escoba o paja), hostales rústicos de montaña y casas de aldea aisladas en valles cerrados. | Parque Natural de Somiedo (Reserva de la Biosfera). La meca nacional del turismo rural enfocado al avistamiento y rastreo guiado del Oso Pardo Cantábrico en libertad. Ofrece espectaculares rutas de senderismo de origen glaciar hacia los Lagos de Somiedo (Lago del Valle y lagos de Saliencia), caminatas por las brañas ganaderas altas, ríos trucheros y senderos de interpretación botánica.') WHERE codigo_ine = '33068';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de alta montaña de piedra caliza, albergues de excursionistas y casas rurales tradicionales unifamiliares optimizadas para montañeros y escaladores. | Puerta de entrada oficial al Parque Nacional de los Picos de Europa (Macizo Central). Punto logístico principal para el senderismo de la Ruta del Cares y de ascensión alpina al mítico Pico Urriellu (Naranjo de Bulnes, la meca de la escalada clásica en España). Ofrece paseos hacia el pueblo colgado de Bulnes (acceso mediante funicular subterráneo), dehesas alpinas, y turismo gastronómico en cuevas de maduración de queso.') WHERE codigo_ine = '05004';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas asturianas solariegas, casas de turismo rural bajas independientes rodeadas de pomaradas (campos de manzanos) y apartamentos vacacionales rústicos. | Comarca de la Sidra, falda de la Sierra de Peñamayor. Ofrece la ruta de senderismo de las Foces del río Pendón (estrecho desfiladero fluvial calizo con pasarelas de madera y puentes de piedra bajo el bosque). Caminatas de media montaña que exploran dehesas verdes de ganado, dehesas forestales de castaños y robles, y rutas micológicas otoñales. 📂 PROVINCIA: CANTABRIA (Cantabria Ampliación de Densidad)') WHERE codigo_ine = '33040';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas cántabras reales rústicas con escudos heráldicos, casonas montañesas tradicionales de sillería con grandes solanas orientadas al sur, y casas integradas en conjuntos históricos. | Reserva Nacional de Saja, Valle de Cabuérniga. Incluye en su término el Conjunto Histórico de Bárcena Mayor (el pueblo más antiguo e intacto de Cantabria). Ofrece rutas de senderismo por la Senda de los Senderos, caminatas fluviales junto al río Argoza, densas masas forestales de hayas primigenias, dehesas y observación de fauna ibérica.') WHERE codigo_ine = '39014';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra y madera optimizadas para el turismo activo, apartamentos de interior con vistas a las colosales moles calizas del valle y posadas rústicas. | Valle del río Asón medio. Capital indiscutible de la espeleología y del turismo de aventura subterráneo en Cantabria por su colosal subsuelo kárstico calado de simas. Rutas de senderismo hacia cuevas con arte rupestre prehistórico (Cueva de Covalanas, Patrimonio de la Humanidad), vías ferratas de montaña con puentes colgantes, dehesas y escalada deportiva.') WHERE codigo_ine = '39057';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales neoclásicas con amplios jardines vinculadas al termalismo histórico de su célebre balneario, casas rurales de piedra junto al río Miera y casonas montañesas. | Comarca de Trasmiera, falda de las Peñas de Rucandio (las "Tetas de Liérganes"). Destaca por su casco urbano medieval de sillería (Conjunto Histórico). Ofrece senderismo fluvial junto al río Miera cruzando su puente romano, dehesas de pasto, dehesas forestales de encinas cantábricas y caminatas de media montaña a picos calizos limítrofes.') WHERE codigo_ine = '39037';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Apartamentos rústicos de madera de castaño, casas rurales con porche integradas en dehesas y viñedos lebaniegos de colina y posadas montañesas. | Entrada norte al Valle de Liébana a través del espectacular e imponente Desfiladero de la Hermida (cañón kárstico calizo con paredes verticales de roca de más de 600 metros). Senderismo por la canal de Urdón hacia el pueblo colgado de Tresviso, rutas cicloturistas de montaña (BTT), dehesas agrícolas de viñedo de montaña y castañares centenarios protegidos. 📂 PROVINCIA: HUESCA (Aragón - Ampliación de Densidad)') WHERE codigo_ine = '39022';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas infanzonas de sillería convertidas en hoteles rurales, complejos de apartamentos rústicos con jardín y casas de pueblo de alquiler íntegro. | Nudo estratégico entre el Valle de Tena y la comarca del Serrablo, bañado por el río Gállego. Rutas de senderismo hacia el recóndito Ermita de Santa Elena encajonado en un estrecho desfiladero, dehesas altas, parques de aventura forestal en tirolinas gigantes, cicloturismo de carretera y senderos de interpretación botánica.') WHERE codigo_ine = '22059';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hotel rural de lujo en un antiguo monasterio rehabilitado del siglo XVII, casas de turismo rural de mampostería antigua a la sombra del castillo y apartamentos rústicos de cara al río Ara. | Valle del río Ara medio, en la comarca del Sobrarbe. Destaca por las pozas naturales de La Gorga de Boltaña (ideales para el baño estival en aguas limpias de montaña), dehesas, rutas senderistas que exploran los pueblos abandonados del viejo Sobrarbe y el pirineo meridional, y senderos micológicos otoñales.') WHERE codigo_ine = '22066';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas tradicionales sorianas rehabilitadas de mampostería de río y madera, apartamentos rurales pequeños para familias y espeleólogos cerca del cauce fluvial. | Custodia el Monumento Natural de La Fuentona de Muriel (conocido como el Ojo de Mar, una espectacular y colosal surgencia kárstica natural o pozo de agua dulce turquesa profunda y cristalina de la que nace el río Abión). Rutas senderistas señalizadas que transitan por la hoz caliza calcárea de la Fuentona bajo sabinas centenarias y nidos de buitres, dehesas altas, paseos botánicos y cuevas kársticas con ríos subterráneos activos.') WHERE codigo_ine = '42124';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales bajas de tapial y piedra caliza con corrales recuperados, apartamentos rústicos familiares a la sombra de su castillo fortificado y posadas rurales. | Extremo oriental meridional, bañado por el río Nágima y lindando con el Embalse de Monteagudo. Custodia la dehesa palustre del embalse, declarada Zona ZEPA por ser un punto clave para el turismo ornitológico de aves acuáticas migratorias (ánades, cigüeñuelas, garzas). Rutas de senderismo plano perimetral, caminatas de dehesa agraria y observación astronómica con cielos limpios nocturnos.') WHERE codigo_ine = '42119';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de mampostería oscura con cubiertas de teja árabe vieja, hostales orientados al dehesa rústica de aislamiento y apartamentos unifamiliares en su casco amurallado de trazado islámico. | En la comarca de la Serranía soriana meridional, transición hacia la provincia de Guadalajara. Ofrece rutas de senderismo exigentes de media montaña que ascienden hacia los altos del cerro del Tarancón, caminatas por los cañones calizos excavados por el río Talegones joven, dehesas y senderos micológicos de encinar húmedo y sabinares centenarios. 📂 PROVINCIA: BURGOS (Castilla y León Ampliación de Densidad)') WHERE codigo_ine = '42155';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas solariegas de turismo rural amplias para grupos, hoteles boutique de interior con encanto medieval en el casco antiguo y fincas de dehesa. | Valle de Tobalina alto, comarca de Las Merindades. Rutas de senderismo suave que bordean las dehesas del río Trueba, paseos cicloturistas llanos de gran recorrido por la antigua línea del Santander-Mediterráneo, caminatas micológicas, y punto base idóneo para explorar los cañones calizos de la zona norte.') WHERE codigo_ine = '09209';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales vinculadas al patrimonio industrial textil del siglo XIX (antiguas hilaturas mecánicas reconvertidas), apartamentos rústicos y posadas de montaña. | Sierra de la Demanda húmeda. Sede de la ruta de senderismo de la Senda de los Cascajales, caminatas bajo la umbría de densos hayedos calcícolas del río Oropesa, dehesas ganaderas altas, dehesas y senderos micológicos de pinar y quejigal, y paseos fotográficos fluviales de montaña.') WHERE codigo_ine = '09274';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de campo y casas de turismo rural integrados en bodegas subterráneas tradicionales de la Ribera del Duero, fincas vinícolas tradicionales de agroturismo. | Comarca de la Ribera del Duero. Rutas de senderismo suave entre dehesas de viñedos centenarios de uva tempranillo, paseos cicloturistas llanos por los caminos de sirga del canal del Duero, dehesas agrarias, turismo gastronómicorural de asados y enoturismo de primer nivel mundial.') WHERE codigo_ine = '09256';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales unifamiliares en el casco fortificado de piedra y caliza, y apartamentos rústicos de montaña. | Borde del Páramo de Masa y cuna de Félix Rodríguez de la Fuente. Cuenta con el espectacular diapiro salino (fenómeno geológico visible desde el espacio). Rutas de senderismo por las antiguas Salinas romanas de evaporación, caminatas de ascensión al castillo calizo sobre el abismo, dehesas, y rutas ornitológicas de grandes rapaces de roca. 📂 PROVINCIA: TERUEL (Aragón - Ampliación de Densidad)') WHERE codigo_ine = '09272';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles de naturaleza de lujo orientados al ecoturismo y la gastronomía micológica de kilómetro cero, masías unifamiliares de piedra dorada rodeadas de pinares. | Matarraña montañoso occidental, lindando con la provincia de Castellón. Destaca por las rutas de senderismo que ascienden a las Peñas de Masmut (colosales farallones verticales de roca caliza rosada), dehesas, avistamiento ornitológico de buitres leonados, rutas de recolección de setas en sus pinares húmedos de altura y circuitos BTT.') WHERE codigo_ine = '44154';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Alojamientos rurales de gran nivel integrados en antiguas casas señoriales medievales con bodegas de vino antiguas, masías rurales con encanto en los campos linderos del llano. | Comarca del Matarraña. Cruce de caminos central de la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares). Rutas senderistas de arte rupestre en el barranco del Calapatá, dehesas y campos llanos agrícolas de olivares y almendros, y paseos fotográficos.') WHERE codigo_ine = '44086';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado, apartamentos rústicos forestales pegados a la espesura del bosque. | Sierra de Albarracín, a más de 1.500 metros de altitud. Uno de los mayores pulmones continuos de pinares de pino silvestre de España. Destaca por el senderismo micológico extremo (paraíso del hongo boletus), dehesas altas, rutas botánicas de las fuentes de Bronchales, avistamiento de ciervos y corzos en libertad y aire puro de altitud. 📂 PROVINCIA: CÁCERES (Extremadura Ampliación de Densidad)') WHERE codigo_ine = '44045';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas bajos rehabilitados con patios extremeños de cal. | Custodia el Monumento Natural de Los Barruecos. Espectacular paisaje granítico de grandes charcas de agua dulce rodeadas de colosales peñas de granito lisas erosionadas (famosas por albergar una de las mayores colonias de cigüeña blanca de Europa), rutas senderistas geológicas, dehesas ganaderas y paseos fotográficos.') WHERE codigo_ine = '10115';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña enriscadas en una colina cónica escarpada con arquitectura tradicional de pizarra y mampostería, apartamentos rústicos de aislamiento. | Geoparque Villuercas-Ibores-Jara alto. Rutas de senderismo de ascensión vertical hacia las ruinas de su castillo medieval encaramado en una peña caliza (vistas espectaculares de los valles del sinclinal), dehesas, observación ornitológica de buitres leonados y alimoches anidando en los cortados rocosos y senderos botánicos de quejigales. 📂 PROVINCIA: LEÓN (Castilla y León Ampliación de Densidad)') WHERE codigo_ine = '10033';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de montaña de piedra caliza tradicionales con muros anchos, apartamentos rústicos optimizados para la aventura y albergues de naturaleza fluvial. | Custodia las Hoces de Vegacervera, un colosal desfiladero kárstico de calizas verticales esculpido por el río Torío. Rutas de senderismo de cañón de gran impacto visual, visitas espeleológicas de aventura a la Cueva de Valporquero cercana (galerías subterráneas activas transitables), dehesas altas, escalada deportiva y rutas micológicas. 📂 PROVINCIA: LLEIDA (Cataluña - Ampliación de Densidad)') WHERE codigo_ine = '24194';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales tradicionales pirenaicos de mampostería oscura de río a los pies de grandes farallones calcáreos, apartamentos rústicos pequeños para deportistas náuticos y casas rurales de montaña. | Confluencia del río Noguera Pallaresa y el río de Santa Magdalena. El mayor punto de embarque para el rafting y el descenso de ríos alpinos en la provincia. Ofrece espectaculares rutas de senderismo hacia el Valle de Cardós y la Coma de Burg dentro del Parque Natural del Alt Pirineu, caminatas fluviales, dehesas ganaderas altas, dehesas y senderos micológicos otoñales extremos y rutas de aislamiento.') WHERE codigo_ine = '25126';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de turismo de interior integradas en el antiguo barrio alfarero de pescadores a orillas del agua, alojamientos rústicos con vistas directas al meandro fluvial y fincas de agroturismo agrícola de frutales. | Asentado sobre un espectacular giro cerrado del río Ebro bajo la silueta de su colosal castillo templario del siglo XII (el cual corona la roca). El mayor hub de turismo fluvial pasivo de la provincia; destaca por las rutas en kayak y piragüismo fluvial siguiendo el curso tranquilo de la Ribera de l''Ebre, paseos etnográficos para cruzar el río en el histórico "Pas de Barca" (transbordador tradicional de madera sin motor propulsado por la corriente), dehesas agrícolas, y caminatas de media montaña por la Sierra de Cardó.') WHERE codigo_ine = '43084';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hoteles boutique rurales con encanto integrados en antiguas bodegas tradicionales y casas solariegas vinculadas a la viticultura heroica de colina, posadas de interior rústicas y apartamentos rurales familiares. | Corazón de la Comarca del Priorat, rodeado de lomas de pizarras desmenuzadas (llicorella). Ofrece rutas que conectan senderos agrícolas entre interminables campos de cepas viejas cultivadas en pendientes extremas y bancales tradicionales. Rutas de senderismo de media montaña que ascienden hacia la Sierra de Montsant meridional, dehesas agrarias de vid, cicloturismo de carretera sin tráfico y enoturismo de primer nivel con su prestigiosa Denominación de Origen Calificada. 📂 PROVINCIA: MALLORCA (Islas Baleares Ampliación de Densidad)') WHERE codigo_ine = '43069';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Antiguas casas de labranza castellano-cántabras de sillería gruesa de piedra caliza con corrales cerrados, posadas rurales de interior con chimenea y fragua rústica recuperada. | Sur de Cantabria (valles altos del río Camesa). Posee uno de los conjuntos megalíticos prehistóricos de menhires más importantes del norte peninsular. Rutas de senderismo histórico de la Senda de los Menhires (recorrido que visita dólmenes e hitos de piedra integrados en prados), senderos por formaciones kársticas menores, valles de llanura cerealista, dehesas y cicloturismo de carretera de colinas suaves sin tráfico.') WHERE codigo_ine = '39092';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Complejos de cabañas forestales de madera mimetizadas bajo el encinar, hostales rurales especializados en turismo de naturaleza y grandes casas de campo aisladas en los valles de la sierra. | Puerta de entrada oficial al Parque Nacional de Cabañeros. Sede de la espectacular ruta de senderismo de la Plaza de los Moros y el sendero de las dehesas de robles y quejigos. Ofrece caminatas por el arroyo de la Chorrera, avistamiento guiado de fauna en libertad (ciervo, buitre negro), senderos micológicos de otoño y cielos negros limpios certificados como Destino Starlight.') WHERE codigo_ine = '13049';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza tradicionales manchegas de fachadas blancas de cal y amplios patios de carruajes, posadas de interior rústicas y apartamentos de cara a su monumental plaza mayor barroca. | Comarca del Campo de Montiel, entorno de llanura alta y dehesa agrícola. Ofrece rutas de senderismo plano de baja dificultad que recorren antiguos senderos ganaderos y cañadas reales, caminatas fotográficas paisajísticas de horizontes infinitos entre viñedos y olivares, cicloturismo de paseo familiar por pistas rurales y observación de estrellas.') WHERE codigo_ine = '13074';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones de agroturismo aisladas en las alturas de la sierra. | En el interior del Parque Natural del Valle de Alcudia y Sierra Madrona, encajonado de forma abrupta en las crestas rocosas de cuarcita. Sede de rutas de senderismo escarpadas hacia el Estrecho de la Hoz (cañón cortado por el río Montoro con pinturas rupestres), caminatas de dehesa mediterránea, rutas de micología de otoño y avistamiento del lince ibérico.') WHERE codigo_ine = '13080';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales excavadas parcialmente en el interior de la colina arcillosa (casas cueva tradicionales), apartamentos de interior con encanto y posadas manchegas de cal y azulejo azul. | Altiplano de la Mancha alta. Sede histórica del paisaje de molinos de viento del Quijote que corona la Sierra de los Molinos. Ofrece rutas de senderismo e interpretación agrícola entre interminables campos de cereal, paseos fotográficos al atardecer en los cerros de caliza, y rutas cicloturistas llanas por caminos vecinales históricos de campiña. 📂 PROVINCIA: TOLEDO (Castilla-La Mancha Ampliación de Densidad)') WHERE codigo_ine = '13028';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Cabañas de madera forestales mimetizadas bajo densos encinares, casas rurales de piedra tradicionales serranas unifamiliares con porches y alojamientos de montaña orientados al turismo activo. | En pleno macizo de los Montes de Toledo altos, a más de 900 metros de altitud. Rutas de senderismo de media y alta montaña que exploran bosques mediterráneos aromáticos de encinas, quejigos y madroños centenarios, caminatas fluviales por el sendero del arroyo de la Dehesa con manantiales limpios de montaña, dehesas altas, senderos micológicos otoñales extremos, avistamiento de ciervos (berrea) y rutas cicloturistas de montaña (BTT).') WHERE codigo_ine = '45153';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo de interior unifamiliares independientes con amplios porches de roca caliza, y pequeños apartamentos rurales rústicos de fin de semana en un valle resguardado de montaña. | Valle interior de los Montes de Toledo, lindando con el Parque Nacional de Cabañeros nororiental. Ofrece las rutas de senderismo arqueológico e histórico hacia el yacimiento arqueológico medieval de Malamoneda (con su necrópolis excavada en la roca viva), dehesas, caminatas geológicas interpretativas por los barrancos de cuarcita, y observación astronómica de cielos negros.') WHERE codigo_ine = '45075';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casonas solariegas toledanas de gran porte, hostales de campo de interior de sillería rústica y apartamentos unifamiliares cerca de los cortados rocosos. | Comarca de los Montes de Toledo. Sede de la espectacular ruta de senderismo que asciende hacia el Castillo de Dos Hermanas (fortaleza medieval en ruinas encaramada de forma imposible sobre un colosal risco de cuarcita). Caminatas forestales de encinar maduro, rutas micológicas y paseos de agroturismo olivarero tradicional.') WHERE codigo_ine = '45109';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales unifamiliares integradas intramuros en una villa medieval fortificada colgada del meandro, y pequeños apartamentos rústicos con vistas directas a los cañones de caliza. | Asentado sobre un monumental meandro cerrado del río Júcar inferior (el "anfiteatro del Júcar"). Ofrece rutas de senderismo fluvial por la Senda de las Huertas, dehesas, caminatas geológicas interpretativas por los cortes calizos de las hoces que aíslan el pueblo, paseos de agroturismo en sus terrazas de cultivo tradicionales, cicloturismo de carretera familiar y ornitología.') WHERE codigo_ine = '02041';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de labranza serranas integradas en pequeñas aldeas de montaña de aislamiento, cabañas forestales de madera y hostales de interior. | En el interior del Parque Natural de los Calares del Mundo y de la Sima. Ofrece la ruta de senderismo de los Cañones del río Mundo alto, caminatas de dehesa forestal bajo inmensos pinares silvestres, senderos de micología micológica de otoño (níscalos), rutas de cicloturismo de montaña (BTT) y paseos de interpretación rural.') WHERE codigo_ine = '02049';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de arquitectura popular andalusí integradas en un casco histórico empedrado labrado en roca caliza, y apartamentos rústicos pequeños de montaña. | Sierra de Segura albacetense meridional. Destaca por su entramado de agua viva con el Charco de las Canales (una poza natural cristalina e histórica de agua de manantial integrada en pleno casco urbano adaptada para el baño estival). Rutas senderistas de media montaña por los cortados de la roca caliza calórea, paseos por huertas medievales tradicionales y senderos botánicos. 📂 PROVINCIA: ZARAGOZA (Aragón - Ampliación de Densidad)') WHERE codigo_ine = '02042';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Hostales rurales especializados en turismo de paso por la Vía de la Plata, casas de labranza tradicionales de montaña baja con chimeneas de leña, y cortijos ganaderos aislados en dehesas forestales. | Puerto de las Marismas, en pleno paso de la histórica Vía de la Plata y de la Sierra de Tentudía. Ofrece rutas de senderismo e interpretación ambiental e histórica que ascienden hacia el Monasterio de Tentudía (el punto más alto de la provincia a 1.100 metros de altitud), dehesas, caminatas por dehesas ganaderas maduras bajo robles melojos y encinas viejas, dehesas ganaderas de porcino ibérico, dehesas micológicas, y turismo gastronómico de secaderos tradicionales.') WHERE codigo_ine = '06085';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de cal blanca unifamiliares con porches de mampostería antigua, apartamentos rústicos a las faldas del cerro de su castillo de Miraflores y posadas rurales de campiña. | Comarca de Llanos de Olivenza meridional, cuenca del río Alcarrache (Biotopo Protegido). Rutas de senderismo fluvial por los senderos del corredor ecológico del río Alcarrache bajo bosques de galería maduros de adelfas y sauces, caminatas que ascienden al castillo calizo con vistas panorámicas de las dehesas del entorno, rutas cicloturistas y ornitología. 📂 PROVINCIA: SALAMANCA (Castilla y León Ampliación de Densidad)') WHERE codigo_ine = '06002';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Posadas reales neoclásicas en antiguas casonas de cantería, casas de labranza tradicionales salmantinas con amplios patios de carruajes, y apartamentos rurales familiares de interior. | Asentado de forma monumental sobre un meandro de roca granítica del río Tormes bajo (Conjunto Histórico). Ofrece la Senda Fluvial del río Tormes, un tramo de bosque de galería maduro e islas protegidas. Rutas de senderismo hacia los campos de dehesa del Campo Charro norte, dehesas ganaderas, dehesas, dehesas micológicas, dehesas ganaderas de vacuno morucho extensivo, dehesas micológicas, paseos de interpretación botánica entre encinas viejas y canchales de granito liso, y rutas micológicas otoñales.') WHERE codigo_ine = '37170';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas de campo serranas tradicionales de piedra caliza con solanas rústicas de madera, hostales de interior y apartamentos rurales pequeños cerca del curso fluvial. | Puerta de entrada sur al Parque Natural de Las Batuecas-Sierra de Francia, en la confluencia de los ríos Alagón, Cuerpo de Hombre y Francia. Ofrece espectaculares rutas de senderismo plano fluvial, caminatas que recorren el paraje de los Tres Ríos con pozas de agua cristalina aptas para el baño veraniego, dehesas, senderos agrícolas entre olivares de montaña y campos de cerezos en terraza, y micología.') WHERE codigo_ine = '37313';
UPDATE municipios SET why_json = json_array('🏡 TURISMO RURAL: Casas rurales de mampostería tradicional del abismo, apartamentos rústicos pequeños optimizados para el turismo activo de interior y posadas con encanto de cañón de río. | En el interior de los acantilados verticales del Parque Natural de Arribes del Duero profundo. Sede del espectacular Mirador del Fraile y de la mítica ruta senderista del Pozo de los Humos inferior. Ofrece paseos por el cañón fluvial con caídas de roca granítica de más de 400 metros de altura sobre las aguas del Duero, cruceros fluviales en barca turística de interior, dehesas mediterráneas, y observación de aves rapaces calcícolas (cigüeña negra).') WHERE codigo_ine = '37014';